import 'package:flutter/material.dart';
import 'package:carousel_slider/carousel_slider.dart';
import 'data/image_data.dart'; // Step 1에서 정의한 데이터 파일

void main() => runApp(const MyApp());

class MyApp extends StatelessWidget {
  const MyApp({super.key});
  @override
  Widget build(BuildContext context) {
    return const MaterialApp(
      title: 'Carousel Slider Demo',
      home: CarouselHomePage(),
    );
  }
}

class CarouselHomePage extends StatelessWidget {
  const CarouselHomePage({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('실무형 캐러셀 슬라이더')), 
      body: Center(
        child: CarouselSlider(
          items: imageSliders, // Step 1에서 정의한 위젯 리스트
          options: CarouselOptions(
            autoPlay: true, // 1. 자동 재생 활성화
            autoPlayInterval: const Duration(seconds: 3), // 2. 재생 간격
            aspectRatio: 2.0, // 3. 가로/세로 비율 (2.0 = 가로가 세로의 2배)
            enlargeCenterPage: true, // 4. 중앙 페이지 확대 효과
            viewportFraction: 0.9, // 5. 화면에서 슬라이드가 차지하는 비율 (0.9는 양 옆이 살짝 보임)
            scrollDirection: Axis.horizontal, // 6. 스크롤 방향 (기본값)
          ),
        ),
      ),
    );
  }
}

class CarouselWithIndicator extends StatefulWidget {
  const CarouselWithIndicator({super.key});

  @override
  State<CarouselWithIndicator> createState() => _CarouselWithIndicatorState();
}

class _CarouselWithIndicatorState extends State<CarouselWithIndicator> {
  int _current = 0;
  final CarouselSliderController _controller = CarouselSliderController();

  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        CarouselSlider(
          items: imageSliders,
          carouselController: _controller, // 컨트롤러 연결
          options: CarouselOptions(
            autoPlay: true,
            enlargeCenterPage: true,
            aspectRatio: 2.0,
            onPageChanged: (index, reason) { // 페이지 변경 시 상태 업데이트
              setState(() {
                _current = index;
              });
            },
          ),
        ),
        // 인디케이터 영역
        Row(
          mainAxisAlignment: MainAxisAlignment.center,
          children: imgList.asMap().entries.map((entry) {
            return GestureDetector(
              onTap: () => _controller.animateToPage(entry.key), // 탭 시 해당 페이지로 이동
              child: Container(
                width: 12.0,
                height: 12.0,
                margin: const EdgeInsets.symmetric(vertical: 8.0, horizontal: 4.0),
                decoration: BoxDecoration(
                  shape: BoxShape.circle,
                  color: (Theme.of(context).brightness == Brightness.dark
                          ? Colors.white
                          : Colors.black)
                      .withOpacity(_current == entry.key ? 0.9 : 0.4), // 현재 페이지 강조
                ),
              ),
            );
          }).toList(),
        ),
      ],
    );
  }
}

// 1. 빌더 패턴 (On-Demand Carousel)
Widget buildOnDemandCarousel() {
  return CarouselSlider.builder(
    itemCount: 100, // 총 100개의 항목을 가정
    options: CarouselOptions(
      aspectRatio: 2.0,
      enlargeCenterPage: true,
      autoPlay: true,
    ),
    itemBuilder: (ctx, index, realIdx) {
      // index는 0부터 itemCount-1까지의 인덱스입니다.
      return Container(
        color: Colors.blueGrey,
        child: Center(child: Text('Item $index', style: const TextStyle(fontSize: 24, color: Colors.white))), 
      );
    },
  );
}

// 2. 무한 스크롤 비활성화 (Noon-Looping Demo)
Widget buildNoLoopingCarousel() {
  return CarouselSlider(
    options: CarouselOptions(
      aspectRatio: 2.0,
      enlargeCenterPage: true,
      enableInfiniteScroll: false, // 무한 스크롤 비활성화
      initialPage: 2, // 시작 페이지 설정
      autoPlay: true,
    ),
    items: imageSliders,
  );
}

// 1. Zoom 확대 전략
Widget buildZoomEnlargeCarousel() {
  return CarouselSlider(
    options: CarouselOptions(
      aspectRatio: 2.0,
      enlargeCenterPage: true,
      enlargeStrategy: CenterPageEnlargeStrategy.zoom, // Zoom 효과 적용
      enlargeFactor: 0.4, // 확대 비율 (기본값 0.3)
    ),
    items: imageSliders,
  );
}

// 2. 수직 슬라이더
Widget buildVerticalCarousel() {
  return CarouselSlider(
    options: CarouselOptions(
      height: 400.0, // 수직 모드에서는 높이 지정이 중요
      aspectRatio: 1.0, // 가로/세로 비율을 1:1로 설정
      enlargeCenterPage: true,
      scrollDirection: Axis.vertical, // 스크롤 방향을 수직으로 변경
      autoPlay: true,
    ),
    items: imageSliders,
  );
}
